# ============================================================
# INSERT
# ============================================================

connection = sqlite3.connect(DATABASE_PATH)
cursor = connection.cursor()

cursor.execute("PRAGMA foreign_keys = ON")

# Clear existing game data and dependent rows first.
cursor.execute("DELETE FROM related_games")
cursor.execute("DELETE FROM game_legendaries")
cursor.execute("DELETE FROM game_starters")
cursor.execute("DELETE FROM game_challenges")
cursor.execute("DELETE FROM game_features")
cursor.execute("DELETE FROM games")

cursor.executemany("""
INSERT INTO games (
    slug,
    name,
    generation,
    display_order,
    region,
    hero_description,
    overview,
    region_description,
    japan_release,
    worldwide_release,
    platform,
    developer,
    publisher,
    average_play_time,
    difficulty,
    accent_color,
    cover_image
)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
""", games)

connection.commit()
connection.close()

print(f"Successfully inserted {len(games)} games into PokeVerse.")
